      pt: ["Área: 2 hectares.", "Redesenhada em 1990.", "Chafariz: 5 metros de diâmetro.", "Área pavimentada: 8.000 m².", "Capacidade: 10.000 pessoas.", "Localização: em frente ao Muleeaage."],
      fr: ["Surface : 2 hectares.", "Réaménagée en 1990.", "Fontaine : 5 mètres de diamètre.", "Surface pavée : 8 000 m².", "Capacité : 10 000 personnes.", "Emplacement : devant Muleeaage."],
